def two_sum(values, goal):
    a = 0
    while a < len(values):
        b = a + 1
        while b < len(values):
            if values[a] + values[b] == goal:
                return [a, b]
            b += 1
        a += 1
    return []

def two_sum(nums, target):
    order = sorted(range(len(nums)), key=lambda i: nums[i])
    lo = 0
    hi = len(order) - 1
    while lo < hi:
        total = nums[order[lo]] + nums[order[hi]]
        if total == target:
            return [order[lo], order[hi]]
        if total < target:
            lo += 1
        else:
            hi -= 1
    return []

