def permute(nums):
    result = [[]]
    for x in nums:
        nxt = []
        for p in result:
            for i in range(len(p) + 1):
                nxt.append(p[:i] + [x] + p[i:])
        result = nxt
    return result

def permute(nums):
    out = []

    def backtrack(path):
        if len(path) == len(nums):
            out.append(list(path))
            return
        for x in nums:
            if x in path:
                continue
            path.append(x)
            backtrack(path)
            path.pop()

    backtrack([])
    return out

def climb_stairs(n):
    if n <= 2:
        return n
    dp = [0] * (n + 1)
    dp[1] = 1
    dp[2] = 2
    for i in range(3, n + 1):
        dp[i] = dp[i - 1] + dp[i - 2]
    return dp[n]

def climb_stairs(n):
    memo = {}

    def go(k):
        if k <= 2:
            return k
        if k in memo:
            return memo[k]
        memo[k] = go(k - 1) + go(k - 2)
        return memo[k]

    return go(n)

def climb_stairs(n):
