def search(nums, target):
    lo = 0
    hi = len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            lo = mid + 1
        else:
            hi = mid - 1
    return -1

import bisect


def search(nums, target):
    position = bisect.bisect_left(nums, target)
    if position < len(nums) and nums[position] == target:
        return position
    return -1

def search(nums, target):
    def lookup(lo, hi):
        if lo > hi:
            return -1
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[mid] < target:
            return lookup(mid + 1, hi)
        return lookup(lo, mid - 1)

    return lookup(0, len(nums) - 1)

